steps.script:
$ErrorActionPreference='Stop';$o=@{patch='none';launch='none'}
$p='C:\TTiTTulares\TT-Editorial-Guard.js'
try{
 $s=[IO.File]::ReadAllText($p,[Text.Encoding]::UTF8)
 $a="if(pages.length>18)fail('TOO_MANY_TABS '+pages.length+'; inspect last-audit.json, protected tabs NOT closed');"
 $b="if(pages.length>48)fail('TOO_MANY_TABS_HARD_CAP '+pages.length+'; preserve protected tabs'); if(pages.length>18)note('EDITORIAL_TAB_SOFT_PRESSURE '+pages.length+'; preserved');"
 if($s.Contains($a)){
  $running=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'"|Where-Object{[string]$_.CommandLine -match 'TT-Editorial-Guard[.]js|Ejecutar[.]js'})
  if($running.Count){$o.patch='deferred_active_runner'}
  else{
   $next=$s.Replace($a,$b).Replace("if(pp.length>18)fail('NO_PROBE too many tabs')","if(pp.length>48)fail('NO_PROBE hard tab cap')")
   $tmp=$p+'.editorial-new.js';$backup=$p+'.pre-tabcap-20261112.bak'
   if(-not(Test-Path $backup)){Copy-Item $p $backup -ErrorAction Stop}
   [IO.File]::WriteAllText($tmp,$next,[Text.UTF8Encoding]::new($false))
   & node.exe --check $tmp 2>$null
   if($LASTEXITCODE -ne 0){throw 'NEW_GUARD_JS_INVALID'}
   Move-Item $tmp $p -Force -ErrorAction Stop
   $o.patch='updated';$o.backup='preserved'
  }
 }elseif($s.Contains('TOO_MANY_TABS_HARD_CAP')){$o.patch='already_updated'}
 else{throw 'UNRECOGNIZED_GUARD_NO_CHANGE'}
 if($o.patch -in @('updated','already_updated')){
  $v=Invoke-RestMethod 'http://127.0.0.1:9223/json/list' -TimeoutSec 5
  $o.tabs=@($v|Where-Object{$_.type -eq 'page'}).Count
  if($o.tabs -gt 48){$o.launch='safety_cap'}
  else{
   $busy=@(Get-CimInstance Win32_Process -Filter "Name='node.exe'"|Where-Object{[string]$_.CommandLine -match 'TT-Editorial-Guard[.]js|Ejecutar[.]js'})
   if($busy.Count){$o.launch='active_runner'}
   else{
    $name='TTiTTulares Local'
    $t=Get-ScheduledTask -TaskName $name -ErrorAction Stop
    if([string]$t.State -eq 'Ready'){Start-ScheduledTask -TaskName $name -ErrorAction Stop;$o.launch='news_task_requested'}else{$o.launch='task_not_ready'}
   }
  }
 }
}catch{$o.error=($_.Exception.Message -replace 'https?://\S+','[URL]')}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
